func (c *Core) cdl2crowsOpenAndFillInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, outBegIdx, outNBElement *int32, outInteger []int32) (*CDL2CROWSStream, error) {
	sp := &CDL2CROWSStream{core: c}
	if retCode := c.cdl2crowsOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, outInteger, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) cdl2crowsOpenInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32) (*CDL2CROWSStream, error) {
	sp := &CDL2CROWSStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outInteger [1]int32
	if retCode := c.cdl2crowsOpenSinkFrame(sp, inOpen, inHigh, inLow, inClose, startIdx, &outBegIdx, &outNBElement, sink_outInteger[:]); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// CDL2CROWSOpen opens a live [CDL2CROWSStream] on a warm-up history, oldest bar
// first, and returns it with its value at the last history bar, the value
// [Core.CDL2CROWS] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDL2CROWSLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for histories of different lengths.
func (c *Core) CDL2CROWSOpen(inOpen, inHigh, inLow, inClose []float64) (*CDL2CROWSStream, int32, error) {
	sp, err := c.cdl2crowsOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDL2CROWSOpenAndFill opens a stream as [Core.CDL2CROWSOpen] does and also
// writes the outputs over the whole history, as [Core.CDL2CROWS] writes them
// for bars 0 through len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDL2CROWSLookback] values and
// share no memory with an input or another output.
//
// The errors are those of [Core.CDL2CROWSOpen], and [BadParam] for an output
// that is empty, too short or sharing memory.
func (c *Core) CDL2CROWSOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDL2CROWSStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdl2crowsLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdl2crowsOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
